11	// ApplyFusedEmaAdam op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	
13	#include <algorithm>
14	#include <cstdint>
15	#include <vector>
16	
17	#include <torch/extension.h>
18	#include <torch/library.h>
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	
23	#include "aclrtlaunch_apply_fused_ema_adam.h"
24	
25	namespace ascend_kernel {
26	
27	constexpr int32_t TILE_SIZE = 256;
28	constexpr int32_t CACHE_LINE_BYTES = 512;
29	
30	std::vector<at::Tensor> apply_fused_ema_adam(
31	    const at::Tensor &grad,
32	    const at::Tensor &varRef,
33	    const at::Tensor &mRef,
34	    const at::Tensor &vRef,
35	    const at::Tensor &sRef,
36	    const at::Tensor &step,
37	    double lr,
38	    double emaDecay,
39	    double beta1,
40	    double beta2,
41	    double eps,
42	    int64_t mode,
43	    bool biasCorrection,
44	    double weightDecay)
45	{
46	    // Input validation
47	    TORCH_CHECK(grad.sizes() == varRef.sizes(), "grad and varRef shapes must match");
48	    TORCH_CHECK(grad.sizes() == mRef.sizes(), "grad and mRef shapes must match");
49	    TORCH_CHECK(grad.sizes() == vRef.sizes(), "grad and vRef shapes must match");
50	    TORCH_CHECK(grad.sizes() == sRef.sizes(), "grad and sRef shapes must match");
51	    TORCH_CHECK(grad.is_contiguous(), "grad must be contiguous");
52	    TORCH_CHECK(varRef.is_contiguous(), "varRef must be contiguous");
53	    TORCH_CHECK(mRef.is_contiguous(), "mRef must be contiguous");
54	    TORCH_CHECK(vRef.is_contiguous(), "vRef must be contiguous");
55	    TORCH_CHECK(sRef.is_contiguous(), "sRef must be contiguous");
56	
57	    auto dtype = grad.scalar_type();
58	    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
59	        "dtype must be float16, float32, or bfloat16");
60	
61	    // dtypeFlag: 0=float32, 1=float16, 2=bfloat16
62	    int64_t dtypeFlag = 0;
63	    int64_t needCast = 0;
64	    if (dtype == at::kHalf) {
65	        dtypeFlag = 1;
66	        needCast = 1;
67	    } else if (dtype == at::kBFloat16) {
68	        dtypeFlag = 2;
69	        needCast = 1;
70	    }
71	
72	    // Total elements (flattened)
73	    int64_t totalLength = grad.numel();
74	
75	    // Compute bias correction factors
76	    int64_t stepVal = step.item<int64_t>();
77	    double beta1Corr = 1.0;
78	    double beta2Corr = 1.0;
79	    if (biasCorrection) {
80	        beta1Corr = 1.0 - std::pow(beta1, stepVal);
81	        beta2Corr = 1.0 - std::pow(beta2, stepVal);
82	    }
83	    // Use double max for safety against division by zero
84	    double invBeta1Corr = (beta1Corr > 1e-15) ? (1.0 / beta1Corr) : 1.0;
85	    double invBeta2Corr = (beta2Corr > 1e-15) ? (1.0 / beta2Corr) : 1.0;
86	
87	    // Block-level tiling: split across cores
88	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManger::GetInstance();
89	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
90	
91	    // Calculate elements per core
92	    int64_t totalLengthCoreAlign = ((totalLength + CACHE_LINE_BYTES - 1) / CACHE_LINE_BYTES) * CACHE_LINE_BYTES;
93	    int64_t dtypeSize = static_cast<int64_t>(grad.element_size());
94	
95	    // UB-level tiling
96	    int64_t tileLength = TILE_SIZE;
97	    int64_t formerNum = totalLength / tileLength;
98	    int64_t formerLength = tileLength;
99	    int64_t tailNum = (totalLength % tileLength > 0) ? 1 : 0;
100	    int64_t tailLength = totalLength % tileLength;
101	
102	    // Tiles per core
103	    int64_t totalTiles = formerNum + tailNum;
104	    int64_t tilesPerCore = (totalTiles + coreNum - 1) / coreNum;
105	
106	    // Output tensors — same shape as input
107	    std::vector<int64_t> outShape(grad.sizes().begin(), grad.sizes().end());
108	    at::Tensor varOut = at::empty(outShape, grad.options());
109	    at::Tensor mOut = at::empty(outShape, grad.options());
110	    at::Tensor vOut = at::empty(outShape, grad.options());
111	    at::Tensor sOut = at::empty(outShape, grad.options());
112	
113	    // All scalar parameters as left-values for EXEC_KERNEL_CMD
114	    float lrVal = static_cast<float>(lr);
115	    float emaDecayVal = static_cast<float>(emaDecay);
116	    float beta1Val = static_cast<float>(beta1);
117	    float beta2Val = static_cast<float>(beta2);
118	    float epsVal = static_cast<float>(eps);
119	    float weightDecayVal = static_cast<float>(weightDecay);
120	    float invBeta1CorrVal = static_cast<float>(invBeta1Corr);
121	    float invBeta2CorrVal = static_cast<float>(invBeta2Corr);
122	
123	    // Launch per core
124	    if (tilesPerCore <= 0 || totalLength <= 0) {
125	        return {varOut, mOut, vOut, sOut};
126	    }
127	
128	    // Process in batches of cores
129	    int64_t blockDim = coreNum;
130	    for (int64_t coreIdx = 0; coreIdx < coreNum; ++coreIdx) {
131	        int64_t coreStart = coreIdx * tilesPerCore;
132	        int64_t coreEnd = std::min(coreStart + tilesPerCore, totalTiles);
133	
134	        if (coreStart >= totalTiles) {
135	            continue;
136	        }
137	
138	        EXEC_KERNEL_CMD(apply_fused_ema_adam, blockDim,
139	            grad, varRef, mRef, vRef, sRef,
140	            varOut, mOut, vOut, sOut,
141	            totalLength, tileLength, formerNum, formerLength, tailNum, tailLength,
142	            coreStart, coreEnd,
143	            lrVal, emaDecayVal, beta1Val, beta2Val, epsVal, weightDecayVal,
144	            invBeta1CorrVal, invBeta2CorrVal,
145	            mode, needCast, dtypeFlag);
146	    }
147	
148	    return {varOut, mOut, vOut, sOut};
149	}
150	
151	} // namespace ascend_kernel
