11	// AscendC ApplyFusedEmaAdam kernel — elementwise Adam + EMA fusion
12	// Supports float32, float16, bfloat16
13	// Inputs (all same shape, flattened 1D): grad, varRef, mRef, vRef, sRef
14	// Outputs (all same shape, flattened 1D): var_out, m_out, v_out, s_out
15	
16	#include "kernel_operator.h"
17	
18	constexpr int32_t BUFFER_NUM = 1;
19	constexpr int32_t TILE_SIZE = 256;
20	
21	// ---------------------------------------------------------------------------
22	// Data movement helpers
23	// ---------------------------------------------------------------------------
24	
25	template <typename T>
26	__aicore__ inline void LoadGmToUb(
27	    AscendC::LocalTensor<T> &dst,
28	    const AscendC::GlobalTensor<T> &src,
29	    uint32_t count)
30	{
31	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
32	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
33	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
34	}
35	
36	template <typename T>
37	__aicore__ inline void StoreUbToGm(
38	    AscendC::GlobalTensor<T> &dst,
39	    AscendC::LocalTensor<T> &src,
40	    uint32_t count)
41	{
42	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
43	    AscendC::DataCopyPad(dst, src, copyParams);
44	}
45	
46	// ---------------------------------------------------------------------------
47	// Type helpers
48	// ---------------------------------------------------------------------------
49	
50	template <typename T>
51	__aicore__ inline AscendC::RoundMode OutputRoundMode()
52	{
53	    if constexpr (std::is_same_v<T, bfloat16_t>) {
54	        return AscendC::RoundMode::CAST_ROUND;
55	    }
56	    return AscendC::RoundMode::CAST_NONE;
57	}
58	
59	template <typename T>
60	__aicore__ inline void PrepareInput(
61	    AscendC::LocalTensor<float> &dst,
62	    AscendC::LocalTensor<T> &src,
63	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
64	    int32_t count)
65	{
66	    if constexpr (std::is_same_v<T, float>) {
67	        dst = src.template ReinterpretCast<float>();
68	    } else {
69	        dst = castBuf.template Get<float>();
70	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
71	        AscendC::PipeBarrier<PIPE_V>();
72	    }
73	}
74	
75	template <typename T>
76	__aicore__ inline void PrepareOutput(
77	    AscendC::LocalTensor<float> &dst,
78	    AscendC::LocalTensor<T> &out,
79	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
80	{
81	    if constexpr (std::is_same_v<T, float>) {
82	        dst = out.template ReinterpretCast<float>();
83	    } else {
84	        dst = castBuf.template Get<float>();
85	    }
86	}
87	
88	template <typename T>
89	__aicore__ inline void FinalizeOutput(
90	    AscendC::LocalTensor<T> &out,
91	    AscendC::LocalTensor<float> &src,
92	    int32_t count)
93	{
94	    if constexpr (!std::is_same_v<T, float>) {
95	        AscendC::Cast(out, src, OutputRoundMode<T>(), count);
96	        AscendC::PipeBarrier<PIPE_V>();
97	    }
98	}
99	
100	// =========================================================================
101	// Main Kernel
102	// =========================================================================
103	
104	template <typename dataType>
105	class ApplyFusedEmaAdamKernel {
106	public:
107	    __aicore__ inline void Init(
108	        GM_ADDR grad,
109	        GM_ADDR varRef,
110	        GM_ADDR mRef,
111	        GM_ADDR vRef,
112	        GM_ADDR sRef,
113	        GM_ADDR varOut,
114	        GM_ADDR mOut,
115	        GM_ADDR vOut,
116	        GM_ADDR sOut,
117	        int64_t totalLength,
118	        int64_t tileLength,
119	        int64_t formerNum,
120	        int64_t formerLength,
121	        int64_t tailNum,
122	        int64_t tailLength,
123	        float lr,
124	        float emaDecay,
125	        float beta1,
126	        float beta2,
127	        float eps,
128	        float weightDecay,
129	        float invBeta1Corr,
130	        float invBeta2Corr,
131	        int64_t mode,
132	        int64_t needCast)
133	    {
134	        totalLength_ = totalLength;
135	        tileLength_ = static_cast<int32_t>(tileLength);
136	        formerNum_ = static_cast<int32_t>(formerNum);
137	        formerLength_ = static_cast<int32_t>(formerLength);
138	        tailNum_ = static_cast<int32_t>(tailNum);
139	        tailLength_ = static_cast<int32_t>(tailLength);
140	        lr_ = lr;
141	        emaDecay_ = emaDecay;
142	        beta1_ = beta1;
143	        beta2_ = beta2;
144	        eps_ = eps;
145	        weightDecay_ = weightDecay;
146	        invBeta1Corr_ = invBeta1Corr;
147	        invBeta2Corr_ = invBeta2Corr;
148	        mode_ = static_cast<int32_t>(mode);
149	        needCast_ = static_cast<int32_t>(needCast);
150	
151	        uint64_t bufSize = static_cast<uint64_t>(totalLength_);
152	        gradGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(grad), bufSize);
153	        varRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(varRef), bufSize);
154	        mRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mRef), bufSize);
155	        vRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(vRef), bufSize);
156	        sRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sRef), bufSize);
157	        varOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(varOut), bufSize);
158	        mOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mOut), bufSize);
159	        vOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(vOut), bufSize);
160	        sOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sOut), bufSize);
161	
162	        if (ASCEND_IS_AIV) {
163	            InitBuffers();
164	        }
165	    }
166	
167	    __aicore__ inline void Process()
168	    {
169	        if (!ASCEND_IS_AIV) { return; }
170	
171	        int32_t coreStart = coreStart_;
172	        int32_t totalTiles = formerNum_ + tailNum_;
173	        if (totalTiles <= 0) { return; }
174	
175	        for (int32_t tileIdx = 0; tileIdx < totalTiles; ++tileIdx) {
176	            int32_t curTileLength = (tileIdx < formerNum_) ? formerLength_ : tailLength_;
177	            if (curTileLength <= 0) { continue; }
178	
179	            int32_t offset = tileIdx * formerLength_;
180	            if (tileIdx >= formerNum_) {
181	                offset = formerNum_ * formerLength_;
182	            }
183	
184	            CopyIn(offset, curTileLength);
185	            Compute(curTileLength);
186	            CopyOut(offset, curTileLength);
187	        }
188	    }
189	
190	    __aicore__ inline void SetCoreRange(int64_t coreStart, int64_t coreEnd)
191	    {
192	        coreStart_ = static_cast<int32_t>(coreStart);
193	        coreEnd_ = static_cast<int32_t>(coreEnd);
194	    }
195	
196	private:
197	    // =====================================================================
198	    // Buffer initialization
199	    // =====================================================================
200	    __aicore__ inline void InitBuffers()
201	    {
202	        uint32_t tileBytes = static_cast<uint32_t>(tileLength_) * sizeof(dataType);
203	        uint32_t tileFloatBytes = static_cast<uint32_t>(tileLength_) * sizeof(float);
204	
205	        // Input queues (VECIN) for each of 5 inputs
206	        pipe_.InitBuffer(gradInQueue_, BUFFER_NUM, tileBytes);
207	        pipe_.InitBuffer(varInQueue_, BUFFER_NUM, tileBytes);
208	        pipe_.InitBuffer(mInQueue_, BUFFER_NUM, tileBytes);
209	        pipe_.InitBuffer(vInQueue_, BUFFER_NUM, tileBytes);
210	        pipe_.InitBuffer(sInQueue_, BUFFER_NUM, tileBytes);
211	
212	        // Output queues (VECOUT) for each of 4 outputs
213	        pipe_.InitBuffer(varOutQueue_, BUFFER_NUM, tileBytes);
214	        pipe_.InitBuffer(mOutQueue_, BUFFER_NUM, tileBytes);
215	        pipe_.InitBuffer(vOutQueue_, BUFFER_NUM, tileBytes);
216	        pipe_.InitBuffer(sOutQueue_, BUFFER_NUM, tileBytes);
217	
218	        // Float32 compute buffers
219	        pipe_.InitBuffer(gradF32Buf_, tileFloatBytes);
220	        pipe_.InitBuffer(varF32Buf_, tileFloatBytes);
221	        pipe_.InitBuffer(mF32Buf_, tileFloatBytes);
222	        pipe_.InitBuffer(vF32Buf_, tileFloatBytes);
223	        pipe_.InitBuffer(sF32Buf_, tileFloatBytes);
224	        pipe_.InitBuffer(mSaveF32Buf_, tileFloatBytes);
225	        pipe_.InitBuffer(vSaveF32Buf_, tileFloatBytes);
226	        pipe_.InitBuffer(tmp1F32Buf_, tileFloatBytes);
227	        pipe_.InitBuffer(tmp2F32Buf_, tileFloatBytes);
228	
229	        // Cast buffers (only for half/bf16)
230	        if constexpr (!std::is_same_v<dataType, float>) {
231	            pipe_.InitBuffer(gradCastBuf_, tileFloatBytes);
232	            pipe_.InitBuffer(varCastBuf_, tileFloatBytes);
233	            pipe_.InitBuffer(mCastBuf_, tileFloatBytes);
234	            pipe_.InitBuffer(vCastBuf_, tileFloatBytes);
235	            pipe_.InitBuffer(sCastBuf_, tileFloatBytes);
236	            pipe_.InitBuffer(varOutCastBuf_, tileFloatBytes);
237	            pipe_.InitBuffer(mOutCastBuf_, tileFloatBytes);
238	            pipe_.InitBuffer(vOutCastBuf_, tileFloatBytes);
239	            pipe_.InitBuffer(sOutCastBuf_, tileFloatBytes);
240	        }
241	    }
242	
243	    // =====================================================================
244	    // CopyIn: Load 5 input tiles from GM to UB
245	    // =====================================================================
246	    __aicore__ inline void CopyIn(int32_t offset, int32_t curTileLength)
247	    {
248	        gradInLocal_ = gradInQueue_.AllocTensor<dataType>();
249	        varInLocal_ = varInQueue_.AllocTensor<dataType>();
250	        mInLocal_ = mInQueue_.AllocTensor<dataType>();
251	        vInLocal_ = vInQueue_.AllocTensor<dataType>();
252	        sInLocal_ = sInQueue_.AllocTensor<dataType>();
253	
254	        LoadGmToUb(gradInLocal_, gradGM_[offset], static_cast<uint32_t>(curTileLength));
255	        LoadGmToUb(varInLocal_, varRefGM_[offset], static_cast<uint32_t>(curTileLength));
256	        LoadGmToUb(mInLocal_, mRefGM_[offset], static_cast<uint32_t>(curTileLength));
257	        LoadGmToUb(vInLocal_, vRefGM_[offset], static_cast<uint32_t>(curTileLength));
258	        LoadGmToUb(sInLocal_, sRefGM_[offset], static_cast<uint32_t>(curTileLength));
259	
260	        gradInQueue_.EnQue(gradInLocal_);
261	        varInQueue_.EnQue(varInLocal_);
262	        mInQueue_.EnQue(mInLocal_);
263	        vInQueue_.EnQue(vInLocal_);
264	        sInQueue_.EnQue(sInLocal_);
265	    }
266	
267	    // =====================================================================
268	    // Compute: Adam + EMA elementwise chain
269	    // =====================================================================
270	    __aicore__ inline void Compute(int32_t curTileLength)
271	    {
272	        // Allocate output buffers
273	        varOutLocal_ = varOutQueue_.AllocTensor<dataType>();
274	        mOutLocal_ = mOutQueue_.AllocTensor<dataType>();
275	        vOutLocal_ = vOutQueue_.AllocTensor<dataType>();
276	        sOutLocal_ = sOutQueue_.AllocTensor<dataType>();
277	
278	        // Get float32 compute buffers
279	        gradF32Local_ = gradF32Buf_.Get<float>();
280	        varF32Local_ = varF32Buf_.Get<float>();
281	        mF32Local_ = mF32Buf_.Get<float>();
282	        vF32Local_ = vF32Buf_.Get<float>();
283	        sF32Local_ = sF32Buf_.Get<float>();
284	        mSaveF32Local_ = mSaveF32Buf_.Get<float>();
285	        vSaveF32Local_ = vSaveF32Buf_.Get<float>();
286	        tmp1F32Local_ = tmp1F32Buf_.Get<float>();
287	        tmp2F32Local_ = tmp2F32Buf_.Get<float>();
288	
289	        // Dequeue inputs
290	        gradInLocal_ = gradInQueue_.DeQue<dataType>();
291	        varInLocal_ = varInQueue_.DeQue<dataType>();
292	        mInLocal_ = mInQueue_.DeQue<dataType>();
293	        vInLocal_ = vInQueue_.DeQue<dataType>();
294	        sInLocal_ = sInQueue_.DeQue<dataType>();
295	
296	        // ---- Step 1: Cast inputs to float32 (if needed) ----
297	        PrepareInput<dataType>(gradF32Local_, gradInLocal_, gradCastBuf_, curTileLength);
298	        PrepareInput<dataType>(varF32Local_, varInLocal_, varCastBuf_, curTileLength);
299	        PrepareInput<dataType>(mF32Local_, mInLocal_, mCastBuf_, curTileLength);
300	        PrepareInput<dataType>(vF32Local_, vInLocal_, vCastBuf_, curTileLength);
301	        PrepareInput<dataType>(sF32Local_, sInLocal_, sCastBuf_, curTileLength);
302	
303	        // ---- Step 2: Apply weight decay to grad (mode 0) ----
304	        if (mode_ == 0) {
305	            // grad_ = grad + weightDecay * varRef
306	            AscendC::Muls(tmp1F32Local_, varF32Local_, weightDecay_, curTileLength);
307	            AscendC::Add(gradF32Local_, gradF32Local_, tmp1F32Local_, curTileLength);
308	        }
309	        // mode == 1: grad_ stays as original grad
310	
311	        // ---- Step 3: m_raw = beta1 * mRef + (1-beta1) * grad_ ----
312	        AscendC::Muls(mF32Local_, mF32Local_, beta1_, curTileLength);
313	        AscendC::Muls(tmp1F32Local_, gradF32Local_, (1.0f - beta1_), curTileLength);
314	        AscendC::Add(mF32Local_, mF32Local_, tmp1F32Local_, curTileLength);
315	        // Save uncorrected m for output
316	        AscendC::DataCopy(mSaveF32Local_, mF32Local_, curTileLength);
317	        AscendC::PipeBarrier<PIPE_V>();
318	
319	        // ---- Step 4: v_raw = beta2 * vRef + (1-beta2) * grad_^2 ----
320	        AscendC::Muls(vF32Local_, vF32Local_, beta2_, curTileLength);
321	        AscendC::Mul(tmp1F32Local_, gradF32Local_, gradF32Local_, curTileLength);
322	        AscendC::Muls(tmp1F32Local_, tmp1F32Local_, (1.0f - beta2_), curTileLength);
323	        AscendC::Add(vF32Local_, vF32Local_, tmp1F32Local_, curTileLength);
324	        // Save uncorrected v for output
325	        AscendC::DataCopy(vSaveF32Local_, vF32Local_, curTileLength);
326	        AscendC::PipeBarrier<PIPE_V>();
327	
328	        // ---- Step 5: Bias correction ----
329	        // next_m = m_raw / beta1_correction = m_raw * inv_beta1_corr
330	        AscendC::Muls(mF32Local_, mF32Local_, invBeta1Corr_, curTileLength);
331	        // next_v = v_raw / beta2_correction = v_raw * inv_beta2_corr
332	        AscendC::Muls(vF32Local_, vF32Local_, invBeta2Corr_, curTileLength);
333	
334	        // ---- Step 6: denom = sqrt(next_v) + eps ----
335	        AscendC::Sqrt(tmp1F32Local_, vF32Local_, curTileLength);
336	        AscendC::Adds(tmp1F32Local_, tmp1F32Local_, eps_, curTileLength);
337	
338	        // ---- Step 7: Compute update ----
339	        // update = next_m / denom (using reciprocal + mul)
340	        AscendC::Reciprocal(tmp2F32Local_, tmp1F32Local_, curTileLength);
341	        AscendC::Mul(tmp2F32Local_, tmp2F32Local_, mF32Local_, curTileLength);
342	
343	        if (mode_ == 1) {
344	            // update += weightDecay * varRef
345	            AscendC::Muls(tmp1F32Local_, varF32Local_, weightDecay_, curTileLength);
346	            AscendC::Add(tmp2F32Local_, tmp2F32Local_, tmp1F32Local_, curTileLength);
347	        }
348	
349	        // ---- Step 8: var_ = varRef - lr * update ----
350	        AscendC::Muls(tmp2F32Local_, tmp2F32Local_, lr_, curTileLength);
351	        AscendC::Sub(varF32Local_, varF32Local_, tmp2F32Local_, curTileLength);
352	
353	        // ---- Step 9: s_ = emaDecay * sRef + (1-emaDecay) * var_ ----
354	        AscendC::Muls(sF32Local_, sF32Local_, emaDecay_, curTileLength);
355	        AscendC::Muls(tmp1F32Local_, varF32Local_, (1.0f - emaDecay_), curTileLength);
356	        AscendC::Add(sF32Local_, sF32Local_, tmp1F32Local_, curTileLength);
357	
358	        // ---- Step 10: Finalize and enqueue outputs ----
359	        // var_out: finalize from varF32Local_ → varOutLocal_
360	        PrepareOutput<dataType>(tmp1F32Local_, varOutLocal_, varOutCastBuf_);
361	        if constexpr (std::is_same_v<dataType, float>) {
362	            AscendC::DataCopy(varOutLocal_, varF32Local_, curTileLength);
363	        } else {
364	            FinalizeOutput<dataType>(varOutLocal_, varF32Local_, curTileLength);
365	        }
366	
367	        // m_out: finalize from mSaveF32Local_ → mOutLocal_
368	        if constexpr (std::is_same_v<dataType, float>) {
369	            AscendC::DataCopy(mOutLocal_, mSaveF32Local_, curTileLength);
370	        } else {
371	            PrepareOutput<dataType>(tmp1F32Local_, mOutLocal_, mOutCastBuf_);
372	            FinalizeOutput<dataType>(mOutLocal_, mSaveF32Local_, curTileLength);
373	        }
374	
375	        // v_out: finalize from vSaveF32Local_ → vOutLocal_
376	        if constexpr (std::is_same_v<dataType, float>) {
377	            AscendC::DataCopy(vOutLocal_, vSaveF32Local_, curTileLength);
378	        } else {
379	            PrepareOutput<dataType>(tmp1F32Local_, vOutLocal_, vOutCastBuf_);
380	            FinalizeOutput<dataType>(vOutLocal_, vSaveF32Local_, curTileLength);
381	        }
382	
383	        // s_out: finalize from sF32Local_ → sOutLocal_
384	        if constexpr (std::is_same_v<dataType, float>) {
385	            AscendC::DataCopy(sOutLocal_, sF32Local_, curTileLength);
386	        } else {
387	            PrepareOutput<dataType>(tmp1F32Local_, sOutLocal_, sOutCastBuf_);
388	            FinalizeOutput<dataType>(sOutLocal_, sF32Local_, curTileLength);
389	        }
390	
391	        // Enqueue outputs
392	        varOutQueue_.EnQue(varOutLocal_);
393	        mOutQueue_.EnQue(mOutLocal_);
394	        vOutQueue_.EnQue(vOutLocal_);
395	        sOutQueue_.EnQue(sOutLocal_);
396	
397	        // Free input buffers
398	        gradInQueue_.FreeTensor(gradInLocal_);
399	        varInQueue_.FreeTensor(varInLocal_);
400	        mInQueue_.FreeTensor(mInLocal_);
401	        vInQueue_.FreeTensor(vInLocal_);
402	        sInQueue_.FreeTensor(sInLocal_);
403	    }
404	
405	    // =====================================================================
406	    // CopyOut: Write 4 output tiles from UB to GM
407	    // =====================================================================
408	    __aicore__ inline void CopyOut(int32_t offset, int32_t curTileLength)
409	    {
410	        varOutLocal_ = varOutQueue_.DeQue<dataType>();
411	        mOutLocal_ = mOutQueue_.DeQue<dataType>();
412	        vOutLocal_ = vOutQueue_.DeQue<dataType>();
413	        sOutLocal_ = sOutQueue_.DeQue<dataType>();
414	
415	        StoreUbToGm(varOutGM_[offset], varOutLocal_, static_cast<uint32_t>(curTileLength));
416	        StoreUbToGm(mOutGM_[offset], mOutLocal_, static_cast<uint32_t>(curTileLength));
417	        StoreUbToGm(vOutGM_[offset], vOutLocal_, static_cast<uint32_t>(curTileLength));
418	        StoreUbToGm(sOutGM_[offset], sOutLocal_, static_cast<uint32_t>(curTileLength));
419	
420	        varOutQueue_.FreeTensor(varOutLocal_);
421	        mOutQueue_.FreeTensor(mOutLocal_);
422	        vOutQueue_.FreeTensor(vOutLocal_);
423	        sOutQueue_.FreeTensor(sOutLocal_);
424	    }
