// AscendC ApplyAdamWV2 kernel — elementwise AdamW optimizer fusion
// Supports float32, float16, bfloat16
// Inputs (all same shape, flattened 1D): grad, varRef, mRef, vRef, maxGradNormRef
// Outputs (all same shape, flattened 1D): varOut, mOut, vOut, maxGradNormOut

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_SIZE = 1024;

// ---------------------------------------------------------------------------
// Data movement helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> &dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Type helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T, typename CastBuf>
__aicore__ inline void PrepareInput(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    CastBuf &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.template Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T, typename CastBuf>
__aicore__ inline void FinalizeOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    CastBuf &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        AscendC::DataCopy(out, src, count);
    } else {
        auto castLocal = castBuf.template Get<float>();
        AscendC::Cast(out, src, OutputRoundMode<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Main Kernel
// =========================================================================

template <typename dataType>
class ApplyAdamWV2Kernel {
public:
    __aicore__ inline void Init(
        GM_ADDR grad,
        GM_ADDR varRef,
        GM_ADDR mRef,
        GM_ADDR vRef,
        GM_ADDR maxGradNormRef,
        GM_ADDR varOut,
        GM_ADDR mOut,
        GM_ADDR vOut,
        GM_ADDR maxGradNormOut,
        int64_t totalLength,
        int64_t tileLength,
        int64_t formerNum,
        int64_t formerLength,
        int64_t tailNum,
        int64_t tailLength,
        float wdFactor,
        float beta1,
        float beta2,
        float oneMinusBeta1,
        float oneMinusBeta2,
        float stepSize,
        float invBias2Sqrt,
        float eps,
        int64_t amsgradMode,
        int64_t maximizeMode)
    {
        totalLength_ = totalLength;
        tileLength_ = static_cast<int32_t>(tileLength);
        formerNum_ = static_cast<int32_t>(formerNum);
        formerLength_ = static_cast<int32_t>(formerLength);
        tailNum_ = static_cast<int32_t>(tailNum);
        tailLength_ = static_cast<int32_t>(tailLength);
        wdFactor_ = wdFactor;
        beta1_ = beta1;
        beta2_ = beta2;
        oneMinusBeta1_ = oneMinusBeta1;
        oneMinusBeta2_ = oneMinusBeta2;
        stepSize_ = stepSize;
        invBias2Sqrt_ = invBias2Sqrt;
        eps_ = eps;
        amsgradMode_ = static_cast<int32_t>(amsgradMode);
        maximizeMode_ = static_cast<int32_t>(maximizeMode);

        uint64_t bufSize = static_cast<uint64_t>(totalLength_);
        gradGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(grad), bufSize);
        varRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(varRef), bufSize);
        mRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mRef), bufSize);
        vRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(vRef), bufSize);
        maxNormRefGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(maxGradNormRef), bufSize);
        varOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(varOut), bufSize);
        mOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(mOut), bufSize);
        vOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(vOut), bufSize);
        maxNormOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(maxGradNormOut), bufSize);

        if (ASCEND_IS_AIV) {
            InitBuffers();
        }
    }

    __aicore__ inline void Process()
    {
        if (!ASCEND_IS_AIV) { return; }

        int32_t totalTiles = formerNum_ + tailNum_;
        if (totalTiles <= 0) { return; }

        for (int32_t tileIdx = 0; tileIdx < totalTiles; ++tileIdx) {
            int32_t curTileLength = (tileIdx < formerNum_) ? formerLength_ : tailLength_;
            if (curTileLength <= 0) { continue; }

            int32_t offset = tileIdx * formerLength_;
            if (tileIdx >= formerNum_) {
                offset = formerNum_ * formerLength_;
            }

            CopyIn(offset, curTileLength);
            Compute(curTileLength);
            CopyOut(offset, curTileLength);
        }
    }

    __aicore__ inline void SetCoreRange(int64_t coreStart, int64_t coreEnd)
    {
        coreStart_ = static_cast<int32_t>(coreStart);
        coreEnd_ = static_cast<int32_t>(coreEnd);
    }

private:
    // =====================================================================
    // Buffer initialization
    // =====================================================================
    __aicore__ inline void InitBuffers()
    {
        uint32_t tileBytes = static_cast<uint32_t>(tileLength_) * sizeof(dataType);
        uint32_t tileFloatBytes = static_cast<uint32_t>(tileLength_) * sizeof(float);

        // Input queues (VECIN) for each of 5 inputs
        pipe_.InitBuffer(gradInQueue_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(varInQueue_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(mInQueue_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(vInQueue_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(maxNormInQueue_, BUFFER_NUM, tileBytes);

        // Output queues (VECOUT) for each of 4 outputs
        pipe_.InitBuffer(varOutQueue_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(mOutQueue_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(vOutQueue_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(maxNormOutQueue_, BUFFER_NUM, tileBytes);

        // Float32 compute buffers (TBuf VECCALC)
        pipe_.InitBuffer(gradF32Buf_, tileFloatBytes);
        pipe_.InitBuffer(varF32Buf_, tileFloatBytes);
        pipe_.InitBuffer(mF32Buf_, tileFloatBytes);
        pipe_.InitBuffer(vF32Buf_, tileFloatBytes);
        pipe_.InitBuffer(maxNormF32Buf_, tileFloatBytes);
        pipe_.InitBuffer(mSaveF32Buf_, tileFloatBytes);
        pipe_.InitBuffer(vSaveF32Buf_, tileFloatBytes);
        pipe_.InitBuffer(tmp1F32Buf_, tileFloatBytes);
        pipe_.InitBuffer(tmp2F32Buf_, tileFloatBytes);

        // Cast buffers (only for half/bf16)
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(gradCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(varCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(mCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(vCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(maxNormCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(varOutCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(mOutCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(vOutCastBuf_, tileFloatBytes);
            pipe_.InitBuffer(maxNormOutCastBuf_, tileFloatBytes);
        }
    }

    // =====================================================================
    // CopyIn: Load 5 input tiles from GM to UB
    // =====================================================================
    __aicore__ inline void CopyIn(int32_t offset, int32_t curTileLength)
    {
        gradInLocal_ = gradInQueue_.AllocTensor<dataType>();
        varInLocal_ = varInQueue_.AllocTensor<dataType>();
        mInLocal_ = mInQueue_.AllocTensor<dataType>();
        vInLocal_ = vInQueue_.AllocTensor<dataType>();
        maxNormInLocal_ = maxNormInQueue_.AllocTensor<dataType>();

        LoadGmToUb(gradInLocal_, gradGM_[offset], static_cast<uint32_t>(curTileLength));
        LoadGmToUb(varInLocal_, varRefGM_[offset], static_cast<uint32_t>(curTileLength));
        LoadGmToUb(mInLocal_, mRefGM_[offset], static_cast<uint32_t>(curTileLength));
        LoadGmToUb(vInLocal_, vRefGM_[offset], static_cast<uint32_t>(curTileLength));
        LoadGmToUb(maxNormInLocal_, maxNormRefGM_[offset], static_cast<uint32_t>(curTileLength));

        gradInQueue_.EnQue(gradInLocal_);
        varInQueue_.EnQue(varInLocal_);
        mInQueue_.EnQue(mInLocal_);
        vInQueue_.EnQue(vInLocal_);
        maxNormInQueue_.EnQue(maxNormInLocal_);
    }

    // =====================================================================
    // Compute: AdamW optimizer elementwise chain
    // =====================================================================
    __aicore__ inline void Compute(int32_t curTileLength)
    {
        // Allocate output buffers
        varOutLocal_ = varOutQueue_.AllocTensor<dataType>();
        mOutLocal_ = mOutQueue_.AllocTensor<dataType>();
        vOutLocal_ = vOutQueue_.AllocTensor<dataType>();
        maxNormOutLocal_ = maxNormOutQueue_.AllocTensor<dataType>();

        // Get float32 compute buffers
        gradF32Local_ = gradF32Buf_.Get<float>();
        varF32Local_ = varF32Buf_.Get<float>();
        mF32Local_ = mF32Buf_.Get<float>();
        vF32Local_ = vF32Buf_.Get<float>();
        maxNormF32Local_ = maxNormF32Buf_.Get<float>();
        mSaveF32Local_ = mSaveF32Buf_.Get<float>();
        vSaveF32Local_ = vSaveF32Buf_.Get<float>();
        tmp1F32Local_ = tmp1F32Buf_.Get<float>();
        tmp2F32Local_ = tmp2F32Buf_.Get<float>();

        // Dequeue inputs
        gradInLocal_ = gradInQueue_.DeQue<dataType>();
        varInLocal_ = varInQueue_.DeQue<dataType>();
        mInLocal_ = mInQueue_.DeQue<dataType>();
        vInLocal_ = vInQueue_.DeQue<dataType>();
        maxNormInLocal_ = maxNormInQueue_.DeQue<dataType>();

        // ---- Step 1: Cast inputs to float32 (if needed) ----
        PrepareInput<dataType>(gradF32Local_, gradInLocal_, gradCastBuf_, curTileLength);
        PrepareInput<dataType>(varF32Local_, varInLocal_, varCastBuf_, curTileLength);
        PrepareInput<dataType>(mF32Local_, mInLocal_, mCastBuf_, curTileLength);
        PrepareInput<dataType>(vF32Local_, vInLocal_, vCastBuf_, curTileLength);
        PrepareInput<dataType>(maxNormF32Local_, maxNormInLocal_, maxNormCastBuf_, curTileLength);

        // ---- Step 2: Apply maximize (negate grad) ----
        if (maximizeMode_ == 1) {
            AscendC::Muls(gradF32Local_, gradF32Local_, -1.0f, curTileLength);
        }

        // ---- Step 3: Parameter weight decay ----
        // var *= (1 - lr * weight_decay) = wdFactor
        AscendC::Muls(varF32Local_, varF32Local_, wdFactor_, curTileLength);

        // ---- Step 4: m = beta1 * m + (1 - beta1) * grad ----
        AscendC::Muls(mF32Local_, mF32Local_, beta1_, curTileLength);
        AscendC::Muls(tmp1F32Local_, gradF32Local_, oneMinusBeta1_, curTileLength);
        AscendC::Add(mF32Local_, mF32Local_, tmp1F32Local_, curTileLength);
        // Save uncorrected m for output
        AscendC::DataCopy(mSaveF32Local_, mF32Local_, curTileLength);
        AscendC::PipeBarrier<PIPE_V>();

        // ---- Step 5: v = beta2 * v + (1 - beta2) * grad^2 ----
        AscendC::Muls(vF32Local_, vF32Local_, beta2_, curTileLength);
        AscendC::Mul(tmp1F32Local_, gradF32Local_, gradF32Local_, curTileLength);
        AscendC::Muls(tmp1F32Local_, tmp1F32Local_, oneMinusBeta2_, curTileLength);
        AscendC::Add(vF32Local_, vF32Local_, tmp1F32Local_, curTileLength);
        // Save uncorrected v for output
        AscendC::DataCopy(vSaveF32Local_, vF32Local_, curTileLength);
        AscendC::PipeBarrier<PIPE_V>();

        // ---- Step 6: Denominator computation ----
        // amsgrad: max_norm = max(max_grad_norm, v)
        //          denom = sqrt(max_norm) / sqrt(bias2) + eps
        // else:    denom = sqrt(v) / sqrt(bias2) + eps
        if (amsgradMode_ == 1) {
            AscendC::Max(maxNormF32Local_, maxNormF32Local_, vF32Local_, curTileLength);
            AscendC::Sqrt(tmp1F32Local_, maxNormF32Local_, curTileLength);
        } else {
            AscendC::Sqrt(tmp1F32Local_, vF32Local_, curTileLength);
        }
        AscendC::Muls(tmp1F32Local_, tmp1F32Local_, invBias2Sqrt_, curTileLength);
        AscendC::Adds(tmp1F32Local_, tmp1F32Local_, eps_, curTileLength);

        // ---- Step 7: Update param ----
        // update = stepSize * m / denom
        // var -= update
        AscendC::Reciprocal(tmp2F32Local_, tmp1F32Local_, curTileLength);
        AscendC::Mul(tmp2F32Local_, tmp2F32Local_, mF32Local_, curTileLength);
        AscendC::Muls(tmp2F32Local_, tmp2F32Local_, stepSize_, curTileLength);
        AscendC::Sub(varF32Local_, varF32Local_, tmp2F32Local_, curTileLength);

        // ---- Step 8: Finalize and enqueue outputs ----
        FinalizeOutput<dataType>(varOutLocal_, varF32Local_, varOutCastBuf_, curTileLength);
        FinalizeOutput<dataType>(mOutLocal_, mSaveF32Local_, mOutCastBuf_, curTileLength);
        FinalizeOutput<dataType>(vOutLocal_, vSaveF32Local_, vOutCastBuf_, curTileLength);
        FinalizeOutput<dataType>(maxNormOutLocal_, maxNormF32Local_, maxNormOutCastBuf_, curTileLength);

        // Enqueue outputs
        varOutQueue_.EnQue(varOutLocal_);
        mOutQueue_.EnQue(mOutLocal_);
        vOutQueue_.EnQue(vOutLocal_);
        maxNormOutQueue_.EnQue(maxNormOutLocal_);

        // Free input buffers
        gradInQueue_.FreeTensor(gradInLocal_);
        varInQueue_.FreeTensor(varInLocal_);
        mInQueue_.FreeTensor(mInLocal_);
        vInQueue_.FreeTensor(vInLocal_);
        maxNormInQueue_.FreeTensor(maxNormInLocal_);
    }

    // =====================================================================
    // CopyOut: Write 4 output tiles from UB to GM
    // =====================================================================
    __aicore__ inline void CopyOut(int32_t offset, int32_t curTileLength)
    {
        varOutLocal_ = varOutQueue_.DeQue<dataType>();
        mOutLocal_ = mOutQueue_.DeQue<dataType>();
        vOutLocal_ = vOutQueue_.DeQue<dataType>();
        maxNormOutLocal_ = maxNormOutQueue_.DeQue<dataType>();

        StoreUbToGm(varOutGM_[offset], varOutLocal_, static_cast<uint32_t>(curTileLength));
        StoreUbToGm(mOutGM_[offset], mOutLocal_, static_cast<uint32_t>(curTileLength));
        StoreUbToGm(vOutGM_[offset], vOutLocal_, static_cast<uint32_t>(curTileLength));
        StoreUbToGm(maxNormOutGM_[offset], maxNormOutLocal_, static_cast<uint32_t>(curTileLength));

        varOutQueue_.FreeTensor(varOutLocal_);
        mOutQueue_.FreeTensor(mOutLocal_);
        vOutQueue_.FreeTensor(vOutLocal_);
        maxNormOutQueue_.FreeTensor(maxNormOutLocal_);
    }

private:
    // Tiling parameters
    int64_t totalLength_ = 0;
    int32_t tileLength_ = 0;
    int32_t formerNum_ = 0;
    int32_t formerLength_ = 0;
    int32_t tailNum_ = 0;
    int32_t tailLength_ = 0;
    int32_t coreStart_ = 0;
    int32_t coreEnd_ = 0;

    // Pre-computed scalars
    float wdFactor_ = 1.0f;
    float beta1_ = 0.0f;
    float beta2_ = 0.0f;
    float oneMinusBeta1_ = 0.0f;
    float oneMinusBeta2_ = 0.0f;
    float stepSize_ = 0.0f;
    float invBias2Sqrt_ = 1.0f;
    float eps_ = 0.0f;
    int32_t amsgradMode_ = 0;
    int32_t maximizeMode_ = 0;

    // Global tensors
    AscendC::GlobalTensor<dataType> gradGM_;
    AscendC::GlobalTensor<dataType> varRefGM_;
    AscendC::GlobalTensor<dataType> mRefGM_;
    AscendC::GlobalTensor<dataType> vRefGM_;
    AscendC::GlobalTensor<dataType> maxNormRefGM_;
    AscendC::GlobalTensor<dataType> varOutGM_;
    AscendC::GlobalTensor<dataType> mOutGM_;
    AscendC::GlobalTensor<dataType> vOutGM_;
    AscendC::GlobalTensor<dataType> maxNormOutGM_;

    // Pipe
    AscendC::TPipe pipe_;

    // Input queues (VECIN)
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gradInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> varInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> mInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> vInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> maxNormInQueue_;

    // Output queues (VECOUT)
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> varOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> mOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> vOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> maxNormOutQueue_;

    // Float32 compute buffers (TBuf VECCALC)
    AscendC::TBuf<AscendC::TPosition::VECCALC> gradF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> varF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> vF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxNormF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mSaveF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> vSaveF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp1F32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp2F32Buf_;

    // Cast buffers (only for half/bf16)
    AscendC::TBuf<AscendC::TPosition::VECCALC> gradCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> varCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> vCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxNormCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> varOutCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> mOutCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> vOutCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxNormOutCastBuf_;

    // Local tensors (typed)
    AscendC::LocalTensor<dataType> gradInLocal_;
    AscendC::LocalTensor<dataType> varInLocal_;
    AscendC::LocalTensor<dataType> mInLocal_;
    AscendC::LocalTensor<dataType> vInLocal_;
    AscendC::LocalTensor<dataType> maxNormInLocal_;
    AscendC::LocalTensor<dataType> varOutLocal_;
    AscendC::LocalTensor<dataType> mOutLocal_;
    AscendC::LocalTensor<dataType> vOutLocal_;
    AscendC::LocalTensor<dataType> maxNormOutLocal_;

    // Local tensors (float32 compute)
    AscendC::LocalTensor<float> gradF32Local_;
    AscendC::LocalTensor<float> varF32Local_;
    AscendC::LocalTensor<float> mF32Local_;
    AscendC::LocalTensor<float> vF32Local_;
    AscendC::LocalTensor<float> maxNormF32Local_;
    AscendC::LocalTensor<float> mSaveF32Local_;
    AscendC::LocalTensor<float> vSaveF32Local_;
    AscendC::LocalTensor<float> tmp1F32Local_;
    AscendC::LocalTensor<float> tmp2F32Local_;
};

// =========================================================================
// Dtype dispatch + kernel entry
// =========================================================================

extern "C" __global__ __aicore__ void apply_adamw_v2(
    GM_ADDR grad,
    GM_ADDR varRef,
    GM_ADDR mRef,
    GM_ADDR vRef,
    GM_ADDR maxGradNormRef,
    GM_ADDR varOut,
    GM_ADDR mOut,
    GM_ADDR vOut,
    GM_ADDR maxGradNormOut,
    int64_t totalLength,
    int64_t tileLength,
    int64_t formerNum,
    int64_t formerLength,
    int64_t tailNum,
    int64_t tailLength,
    int64_t coreStart,
    int64_t coreEnd,
    float wdFactor,
    float beta1,
    float beta2,
    float oneMinusBeta1,
    float oneMinusBeta2,
    float stepSize,
    float invBias2Sqrt,
    float eps,
    int64_t amsgradMode,
    int64_t maximizeMode,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        ApplyAdamWV2Kernel<float> kernel;
        kernel.Init(grad, varRef, mRef, vRef, maxGradNormRef,
            varOut, mOut, vOut, maxGradNormOut,
            totalLength, tileLength, formerNum, formerLength, tailNum, tailLength,
            wdFactor, beta1, beta2, oneMinusBeta1, oneMinusBeta2,
            stepSize, invBias2Sqrt, eps, amsgradMode, maximizeMode);
        kernel.SetCoreRange(coreStart, coreEnd);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        ApplyAdamWV2Kernel<half> kernel;
        kernel.Init(grad, varRef, mRef, vRef, maxGradNormRef,
            varOut, mOut, vOut, maxGradNormOut,
            totalLength, tileLength, formerNum, formerLength, tailNum, tailLength,
            wdFactor, beta1, beta2, oneMinusBeta1, oneMinusBeta2,
            stepSize, invBias2Sqrt, eps, amsgradMode, maximizeMode);
        kernel.SetCoreRange(coreStart, coreEnd);
        kernel.Process();
    } else {
        ApplyAdamWV2Kernel<bfloat16_t> kernel;
        kernel.Init(grad, varRef, mRef, vRef, maxGradNormRef,
            varOut, mOut, vOut, maxGradNormOut,
            totalLength, tileLength, formerNum, formerLength, tailNum, tailLength,
            wdFactor, beta1, beta2, oneMinusBeta1, oneMinusBeta2,
            stepSize, invBias2Sqrt, eps, amsgradMode, maximizeMode);
        kernel.SetCoreRange(coreStart, coreEnd);
        kernel.Process();
    }
