// ApplyAdamWV2 op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_apply_adamw_v2.h"

namespace ascend_kernel {

constexpr int64_t TILE_SIZE = 1024;
constexpr int64_t CACHE_LINE_BYTES = 512;

std::vector<at::Tensor> apply_adamw_v2(
    const at::Tensor &varRef,
    const at::Tensor &mRef,
    const at::Tensor &vRef,
    const at::Tensor &grad,
    const at::Tensor &step,
    const at::Tensor &maxGradNormRef,
    double lr,
    double beta1,
    double beta2,
    double weightDecay,
    double eps,
    bool amsgrad,
    bool maximize)
{
    // Input validation
    TORCH_CHECK(grad.sizes() == varRef.sizes(), "grad and varRef shapes must match");
    TORCH_CHECK(grad.sizes() == mRef.sizes(), "grad and mRef shapes must match");
    TORCH_CHECK(grad.sizes() == vRef.sizes(), "grad and vRef shapes must match");
    TORCH_CHECK(grad.sizes() == maxGradNormRef.sizes(), "grad and maxGradNormRef shapes must match");
    TORCH_CHECK(grad.is_contiguous(), "grad must be contiguous");
    TORCH_CHECK(varRef.is_contiguous(), "varRef must be contiguous");
    TORCH_CHECK(mRef.is_contiguous(), "mRef must be contiguous");
    TORCH_CHECK(vRef.is_contiguous(), "vRef must be contiguous");
    TORCH_CHECK(maxGradNormRef.is_contiguous(), "maxGradNormRef must be contiguous");

    auto dtype = varRef.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
        "dtype must be float16, float32, or bfloat16");

    // dtypeFlag: 0=float32, 1=float16, 2=bfloat16
    int64_t dtypeFlag = 0;
    if (dtype == at::kHalf) {
        dtypeFlag = 1;
    } else if (dtype == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Total elements (flattened)
    int64_t totalLength = grad.numel();

    // Compute bias correction factors and pre-computed scalars
    double stepVal = static_cast<double>(step.item<int64_t>()) + 1.0; // step stores T-1
    double bias1 = 1.0 - std::pow(beta1, stepVal);
    double bias2 = 1.0 - std::pow(beta2, stepVal);

    double stepSize = (bias1 > 1e-15) ? (lr / bias1) : lr;
    double bias2Sqrt = std::sqrt(bias2);
    double invBias2Sqrt = (bias2Sqrt > 1e-15) ? (1.0 / bias2Sqrt) : 1.0;
    double wdFactor = 1.0 - lr * weightDecay;

    // Block-level tiling: split across cores
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());

    // Tiling
    int64_t tileLength = TILE_SIZE;
    int64_t formerNum = totalLength / tileLength;
    int64_t formerLength = tileLength;
    int64_t tailNum = (totalLength % tileLength > 0) ? 1 : 0;
    int64_t tailLength = totalLength % tileLength;

    // Tiles per core
    int64_t totalTiles = formerNum + tailNum;
    int64_t tilesPerCore = (totalTiles + coreNum - 1) / coreNum;

    // Output tensors — same shape as input
    std::vector<int64_t> outShape(grad.sizes().begin(), grad.sizes().end());
    at::Tensor varOut = at::empty(outShape, grad.options());
    at::Tensor mOut = at::empty(outShape, grad.options());
    at::Tensor vOut = at::empty(outShape, grad.options());
    at::Tensor maxGradNormOut = at::empty(outShape, grad.options());

    // All scalar parameters as left-values for EXEC_KERNEL_CMD
    float wdFactorVal = static_cast<float>(wdFactor);
    float beta1Val = static_cast<float>(beta1);
    float beta2Val = static_cast<float>(beta2);
    float oneMinusBeta1Val = static_cast<float>(1.0 - beta1);
    float oneMinusBeta2Val = static_cast<float>(1.0 - beta2);
    float stepSizeVal = static_cast<float>(stepSize);
    float invBias2SqrtVal = static_cast<float>(invBias2Sqrt);
    float epsVal = static_cast<float>(eps);
    int64_t amsgradModeVal = amsgrad ? 1 : 0;
    int64_t maximizeModeVal = maximize ? 1 : 0;

    // Launch per core batch
    if (tilesPerCore <= 0 || totalLength <= 0) {
        if (amsgrad) {
            return {varOut, mOut, vOut, maxGradNormOut};
        }
        return {varOut, mOut, vOut};
    }

    int64_t blockDim = coreNum;
    for (int64_t coreIdx = 0; coreIdx < coreNum; ++coreIdx) {
        int64_t coreStart = coreIdx * tilesPerCore;
        int64_t coreEnd = std::min(coreStart + tilesPerCore, totalTiles);

        if (coreStart >= totalTiles) {
            continue;
        }

        EXEC_KERNEL_CMD(apply_adamw_v2, blockDim,
            grad, varRef, mRef, vRef, maxGradNormRef,
            varOut, mOut, vOut, maxGradNormOut,
            totalLength, tileLength, formerNum, formerLength, tailNum, tailLength,
            coreStart, coreEnd,
            wdFactorVal, beta1Val, beta2Val,
            oneMinusBeta1Val, oneMinusBeta2Val,
            stepSizeVal, invBias2SqrtVal, epsVal,
            amsgradModeVal, maximizeModeVal, dtypeFlag);
    }

    if (amsgrad) {
        return {varOut, mOut, vOut, maxGradNormOut};
    }
    return {varOut, mOut, vOut};
}

} // namespace ascend_kernel
